(function(root){
  'use strict';
  const mod=(n,p)=>((n%p)+p)%p;
  function repeats(o,loop){return o.repeat==='loop'||(o.repeat==='auto'&&o.x>=loop.start&&o.x<loop.end);}
  // Coordinates are scene pixels. Layer order and object order are back to front.
  // A loop object repeats on [start, +infinity). Copies crossing the seam wrap.
  // An auto object whose top-left x precedes start is a one-time intro object.
  function instances(o,loop,minX,maxX,periodic=true){
    if(!periodic||!repeats(o,loop))return o.x+o.width>=minX&&o.x<=maxX?[{x:o.x,copy:0,clipLeft:null}]:[];
    const length=loop.end-loop.start,base=loop.start+mod(o.x-loop.start,length),out=[];
    const first=Math.ceil((Math.max(minX,loop.start)-base-o.width)/length),last=Math.floor((maxX-base)/length);
    for(let k=first;k<=last;k++){const x=base+k*length;if(x+o.width>loop.start)out.push({x,copy:x-o.x,clipLeft:loop.start});}
    return out;
  }
  function paint(ctx,img,o,x){
    ctx.save();ctx.globalAlpha*=o.opacity??1;
    ctx.translate(x+(o.flipX?o.width:0),o.y+(o.flipY?o.height:0));
    ctx.scale(o.flipX?-1:1,o.flipY?-1:1);ctx.drawImage(img,0,0,o.width,o.height);ctx.restore();
  }
  function render(ctx,scene,images,cameraX=0,options={}){
    const width=options.width??scene.canvas.width,height=options.height??scene.canvas.height;
    const viewport=options.viewportWidth??scene.canvas.width;
    ctx.save();ctx.scale(width/viewport,height/scene.canvas.height);ctx.beginPath();ctx.rect(0,0,viewport,scene.canvas.height);ctx.clip();
    if(options.clear!==false)ctx.clearRect(0,0,viewport,scene.canvas.height);
    for(const l of scene.layers){
      if(l.visible===false||(options.onlyLayer&&l.id!==options.onlyLayer))continue;
      const offset=options.designOffset!==undefined?options.designOffset:cameraX*l.parallax;
      ctx.save();ctx.globalAlpha=l.opacity??1;
      for(const o of l.objects){
        const img=images.get?images.get(o.assetId):images[o.assetId];if(!img||o.visible===false)continue;
        for(const p of instances(o,scene.loop,offset,offset+viewport)){
          ctx.save();if(p.clipLeft!==null){ctx.beginPath();ctx.rect(p.clipLeft-offset,0,viewport+Math.abs(offset)+scene.loop.end,scene.canvas.height);ctx.clip();}
          paint(ctx,img,o,p.x-offset);ctx.restore();
        }
      }ctx.restore();
    }ctx.restore();
  }
  const api={instances,repeats,paint,render};root.ParallaxRuntime=api;
  if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
